{
  "ref": "spec:openapi",
  "content": {
    "format": "openapi-3.1",
    "title": "FleetGlass Telematics \u2014 a vehicle-telemetry platform exposing fleet position, sensor, and trip-history APIs to logistics integrators. API",
    "served_at": "/openapi.json",
    "description": "OpenAPI 3.1 spec for the FleetGlass Telematics \u2014 a vehicle-telemetry platform exposing fleet position, sensor, and trip-history APIs to logistics integrators. API, inlined below. All endpoints are relative paths on the same host; construct requests with execute().",
    "document": {
      "openapi": "3.1.0",
      "info": {
        "title": "FleetGlass Telematics \u2014 a vehicle-telemetry platform exposing fleet position, sensor, and trip-history APIs to logistics integrators. API",
        "version": "1.0.0",
        "description": "FleetGlass REST API: ingest and query vehicle telemetry (GPS pings, OBD sensor frames, trip summaries, geofence events) across multiple legacy and current API surfaces accumulated over years of acquisitions."
      },
      "servers": [
        {
          "url": "http://localhost:9001"
        }
      ],
      "paths": {
        "/openapi.json": {
          "get": {
            "summary": "OpenAPI spec doc",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/oauth/token": {
          "post": {
            "summary": "OAuth client_credentials",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/catalog": {
          "get": {
            "summary": "Resource catalog listing canonical endpoints",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v1/locations": {
          "get": {
            "summary": "Legacy vehicle locations (deprecated)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/pings": {
          "get": {
            "summary": "Transitional GPS pings (deprecated)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/positions": {
          "get": {
            "summary": "Canonical current vehicle positions",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v1/journeys": {
          "get": {
            "summary": "Legacy journeys (deprecated)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/routes": {
          "get": {
            "summary": "Route planning resource (NOT trip history)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/trips": {
          "get": {
            "summary": "Canonical trip summaries",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/sensor-frames": {
          "get": {
            "summary": "Canonical OBD sensor frames",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/sensors": {
          "get": {
            "summary": "Legacy aggregate sensor readings (deprecated)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/geofence-events": {
          "get": {
            "summary": "Geofence crossing events",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/geofences": {
          "get": {
            "summary": "Geofence definitions (not events)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
  "updated_at": "2026-07-29T05:57:26.084964+00:00"
}
